1	export type Cell = [number, number];
2	
3	const cellKey = ([x, y]: Cell): string => `${x},${y}`;
4	
5	const neighbors = ([x, y]: Cell): Cell[] => [
6	  [x - 1, y - 1],
7	  [x, y - 1],
8	  [x + 1, y - 1],
9	  [x - 1, y],
10	  [x + 1, y],
11	  [x - 1, y + 1],
12	  [x, y + 1],
13	  [x + 1, y + 1],
14	];
15	
16	const isAliveNextGeneration = (isAlive: boolean, liveNeighbors: number): boolean =>
17	  isAlive ? liveNeighbors === 2 || liveNeighbors === 3 : liveNeighbors === 3;
18	
19	const uniqueByPosition = (cells: Cell[]): Map<string, Cell> =>
20	  new Map(cells.map((cell) => [cellKey(cell), cell]));
21	
22	export const nextGeneration = (liveCells: Cell[]): Cell[] => {
23	  const living = uniqueByPosition(liveCells);
24	  const isAliveNow = (cell: Cell): boolean => living.has(cellKey(cell));
25	  const liveNeighborCount = (cell: Cell): number =>
26	    neighbors(cell).filter(isAliveNow).length;
27	
28	  const cellsToEvaluate = uniqueByPosition(
29	    liveCells.flatMap((cell) => [cell, ...neighbors(cell)]),
30	  );
31	
32	  return [...cellsToEvaluate.values()].filter((cell) =>
33	    isAliveNextGeneration(isAliveNow(cell), liveNeighborCount(cell)),
34	  );
35	};
