7	describe("Game of Life - next generation", () => {
8	  it("returns an empty grid for an empty grid — [] → []", () => {
9	    expect(nextGeneration([])).toEqual([]);
10	  });
11	  it("kills a single lone cell (0 neighbors) — [(0,0)] → []", () => {
12	    expect(nextGeneration([[0, 0]])).toEqual([]);
13	  });
14	  it("Rule 1 Underpopulation: kills both cells of a pair (1 neighbor each) — [(0,1),(1,1)] → []", () => {
15	    expect(
16	      nextGeneration([
17	        [0, 1],
18	        [1, 1],
19	      ]),
20	    ).toEqual([]);
21	  });
22	  it("Rule 2 Survival: a live cell with 3 live neighbors lives on — (1,1) survives", () => {
23	    const result = nextGeneration([
24	      [0, 0],
25	      [1, 0],
26	      [2, 0],
27	      [1, 1],
28	    ]);
29	
30	    expect(sorted(result)).toEqual(
31	      sorted([
32	        [0, 0],
33	        [1, 0],
34	        [2, 0],
